def score(program: str) -> float:
    try:
        t = ast.parse(program)
    except Exception:
        return 0.0
    ns = list(ast.walk(t))
    kinds = {type(n).__name__ for n in ns}
    leaves = sum(1 for n in ns if not list(ast.iter_child_nodes(n)))
    return min(1.0, len(kinds) / 40 + leaves / len(ns) / 2)

